"""Merge Codex++ overlay TOML into ~/.codex/config.toml (plugins, marketplaces, MCP)."""
from __future__ import annotations

import json
import os
import re
import sys
import tomllib
from pathlib import Path


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8-sig")


def strip_sections(text: str, section_names: set[str]) -> str:
    """Remove TOML table sections by exact header name (without brackets)."""
    if not section_names:
        return text

    lines = text.splitlines(keepends=True)
    out: list[str] = []
    skipping = False

    header_re = re.compile(r'^\s*\[(.+?)\]\s*$')

    for line in lines:
        m = header_re.match(line.rstrip("\r\n"))
        if m:
            header = m.group(1).strip()
            # Normalize quoted plugin keys: plugins."foo@bar" -> keep as-is in set
            if header in section_names:
                skipping = True
                continue
            skipping = False
            out.append(line)
            continue

        if not skipping:
            out.append(line)

    return "".join(out).rstrip() + "\n"


def collect_section_names(text: str, prefix: str) -> set[str]:
    names: set[str] = set()
    header_re = re.compile(r'^\s*\[(.+?)\]\s*$')
    for line in text.splitlines():
        m = header_re.match(line)
        if not m:
            continue
        header = m.group(1).strip()
        if header == prefix or header.startswith(prefix + "."):
            names.add(header)
        # plugins use plugins."name@market"
        if prefix == "plugins" and header.startswith('plugins."'):
            names.add(header)
        if prefix == "marketplaces" and header.startswith("marketplaces."):
            names.add(header)
    return names


def parse_mcp_server_names(text: str) -> set[str]:
    names: set[str] = set()
    try:
        data = tomllib.loads(text)
    except tomllib.TOMLDecodeError:
        return names
    mcp = data.get("mcp_servers")
    if isinstance(mcp, dict):
        names.update(mcp.keys())
    return names


def load_overlays(
    codex_home: Path,
    settings_path: Path,
    overlay_path: Path,
    mcp_overlay_path: Path,
) -> tuple[str, str]:
    common = ""
    context = ""

    if settings_path.is_file():
        settings = json.loads(read_text(settings_path))
        common = (settings.get("relayCommonConfigContents") or "").strip()
        context = (settings.get("relayContextConfigContents") or "").strip()

    if not common and overlay_path.is_file():
        common = read_text(overlay_path).strip()

    if not context and mcp_overlay_path.is_file():
        context = read_text(mcp_overlay_path).strip()

    return common, context


def merge_config(
    config_path: Path,
    common_overlay: str,
    context_overlay: str,
) -> dict[str, int]:
    if not config_path.is_file():
        raise FileNotFoundError(f"config not found: {config_path}")

    base = read_text(config_path)

    # Strip plugins/marketplaces from base before merge
    plugin_names = collect_section_names(base, "plugins")
    plugin_names.update(collect_section_names(base, 'plugins."'))
    market_names = collect_section_names(base, "marketplaces")
    strip_names = plugin_names | market_names
    merged = strip_sections(base, strip_names)

    # Strip MCP servers that appear in context overlay (overlay wins)
    mcp_to_replace: set[str] = set()
    if context_overlay:
        mcp_to_replace = parse_mcp_server_names(context_overlay)
        if mcp_to_replace:
            mcp_headers = {f"mcp_servers.{n}" for n in mcp_to_replace}
            # Also strip env subtables
            for n in mcp_to_replace:
                mcp_headers.add(f"mcp_servers.{n}.env")
            merged = strip_sections(merged, mcp_headers)

    parts = [merged.rstrip()]
    if context_overlay:
        parts.append(context_overlay.strip())
    if common_overlay:
        parts.append(common_overlay.strip())

    final_text = "\n\n".join(p for p in parts if p) + "\n"

    tmp = config_path.with_suffix(".toml.merge.tmp")
    tmp.write_text(final_text, encoding="utf-8")
    tmp.replace(config_path)

    result = tomllib.loads(final_text)
    plugins = result.get("plugins") or {}
    marketplaces = result.get("marketplaces") or {}
    mcp = result.get("mcp_servers") or {}

    return {
        "plugins": len(plugins) if isinstance(plugins, dict) else 0,
        "marketplaces": len(marketplaces) if isinstance(marketplaces, dict) else 0,
        "mcp": len(mcp) if isinstance(mcp, dict) else 0,
    }


def main() -> int:
    codex_home = Path(os.environ.get("CODEX_HOME", Path.home() / ".codex"))
    config_path = codex_home / "config.toml"
    settings_path = Path.home() / ".codex-session-delete" / "settings.json"
    overlay_path = codex_home / "codex-plus-overlay.toml"
    mcp_overlay_path = codex_home / "codex-plus-mcp-overlay.toml"

    if len(sys.argv) > 1:
        codex_home = Path(sys.argv[1])
        config_path = codex_home / "config.toml"

    common, context = load_overlays(codex_home, settings_path, overlay_path, mcp_overlay_path)

    if not common and not context:
        print("merge_skip no overlay sources")
        return 1

    counts = merge_config(config_path, common, context)
    print(
        f"merge_ok plugins={counts['plugins']} marketplaces={counts['marketplaces']} mcp={counts['mcp']}"
    )

    # Key work plugins check
    text = read_text(config_path)
    for key in ("figma@openai-curated", "github@openai-curated", "slack@openai-curated"):
        ok = f'plugins."{key}"' in text or f"[plugins.\"{key}\"]" in text
        print(f"merge_check {key}={'yes' if ok else 'no'}")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

