'use strict';

const { spawn, execFile } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');

const FIX_DIR = path.join(process.env.LOCALAPPDATA || '', 'CodexFix');
const LOG_PATH = path.join(FIX_DIR, 'config-watchdog.log');
const CODEX_HOME = path.join(os.homedir(), '.codex');
const CONFIG_PATH = path.join(CODEX_HOME, 'config.toml');
const OVERLAY_PATH = path.join(CODEX_HOME, 'codex-plus-overlay.toml');
const SETTINGS_PATH = path.join(os.homedir(), '.codex-session-delete', 'settings.json');
const MERGE_PS1 = path.join(os.homedir(), '.ai-workspace', 'scripts', 'merge-codex-config.ps1');

const POLL_MS = 5000;
const DEBOUNCE_MS = 2000;
const MIN_PLUGINS = 170;

let mergeInFlight = false;
let debounceTimer = null;
let lastPluginCount = -1;

function log(message) {
  try {
    fs.mkdirSync(FIX_DIR, { recursive: true });
    fs.appendFileSync(LOG_PATH, `[${new Date().toISOString()}] ${message}\n`, 'utf8');
  } catch {
    // ignore
  }
}

function hasOverlaySources() {
  try {
    if (fs.existsSync(OVERLAY_PATH) && fs.statSync(OVERLAY_PATH).size > 100) {
      return true;
    }
    if (fs.existsSync(SETTINGS_PATH)) {
      const settings = JSON.parse(fs.readFileSync(SETTINGS_PATH, 'utf8'));
      const common = settings.relayCommonConfigContents || '';
      if (common.length > 100) {
        return true;
      }
    }
  } catch (error) {
    log(`hasOverlaySources error: ${error}`);
  }
  return false;
}

function countPluginsInConfig() {
  try {
    if (!fs.existsSync(CONFIG_PATH)) {
      return 0;
    }
    const text = fs.readFileSync(CONFIG_PATH, 'utf8');
    const matches = text.match(/\[plugins\."[^"]+"\]/g);
    return matches ? matches.length : 0;
  } catch (error) {
    log(`countPlugins error: ${error}`);
    return 0;
  }
}

function runMerge(reason) {
  if (mergeInFlight) {
    return;
  }
  if (!fs.existsSync(MERGE_PS1)) {
    log(`merge_skip missing script: ${MERGE_PS1}`);
    return;
  }
  if (!hasOverlaySources()) {
    log(`merge_skip no overlay (${reason})`);
    return;
  }

  mergeInFlight = true;
  log(`merge_start reason=${reason}`);

  const child = spawn(
    'powershell.exe',
    ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', MERGE_PS1],
    { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] }
  );

  let stdout = '';
  let stderr = '';
  child.stdout.on('data', (chunk) => {
    stdout += chunk.toString();
  });
  child.stderr.on('data', (chunk) => {
    stderr += chunk.toString();
  });

  child.on('close', (code) => {
    mergeInFlight = false;
    const line = (stdout || stderr).trim().split('\n').filter(Boolean).pop() || '';
    if (code === 0) {
      lastPluginCount = countPluginsInConfig();
      log(`merge_ok code=${code} plugins=${lastPluginCount} ${line}`);
    } else {
      log(`merge_fail code=${code} ${line} ${stderr.trim()}`);
    }
  });
}

function scheduleMerge(reason) {
  if (debounceTimer) {
    clearTimeout(debounceTimer);
  }
  debounceTimer = setTimeout(() => {
    debounceTimer = null;
    runMerge(reason);
  }, DEBOUNCE_MS);
}

function poll() {
  const count = countPluginsInConfig();
  if (count < MIN_PLUGINS && hasOverlaySources()) {
    if (count !== lastPluginCount) {
      log(`poll_detect plugins=${count} (< ${MIN_PLUGINS})`);
      runMerge('poll');
    }
  } else if (count >= MIN_PLUGINS) {
    lastPluginCount = count;
  }
}

function watchConfig() {
  if (!fs.existsSync(CONFIG_PATH)) {
    log('watch_wait config.toml not found yet');
    return;
  }
  try {
    fs.watch(CONFIG_PATH, { persistent: true }, () => {
      scheduleMerge('watch');
    });
    log(`watch_ok ${CONFIG_PATH}`);
  } catch (error) {
    log(`watch_fail ${error}`);
  }
}

function main() {
  log('watchdog_start');
  lastPluginCount = countPluginsInConfig();
  log(`initial_plugins=${lastPluginCount}`);

  if (lastPluginCount < MIN_PLUGINS && hasOverlaySources()) {
    runMerge('startup');
  }

  watchConfig();
  setInterval(poll, POLL_MS);
}

main();

